// TestStringPoliciesMatchReleaseBytes: every policy of the one JSON string
// writer writes exactly release's bytes. Source and log are release's own
// output; HTML-escaped is release's source output with '<', '>' and '&' as the
// standard \u003c, \u003e and \u0026 (release had no HTML-escaped
// writer of its own; encoding/json agrees on every valid UTF-8 input).
func TestStringPoliciesMatchReleaseBytes(t *testing.T) {
	decode := func(s string) string {
		b, err := hex.DecodeString(s)
		require.NoError(t, err)
		return string(b)
	}
	html := strings.NewReplacer("<", `\u003c`, ">", `\u003e`, "&", `\u0026`)
	for i, c := range releaseStringCases {
		input, source, log := decode(c.input), decode(c.source), decode(c.log)
		require.Equal(t, source, string(AppendString(nil, input)), "source policy, case %d", i)
		require.Equal(t, log, string(AppendLogString(nil, input)), "log policy, case %d", i)
		require.Equal(t, html.Replace(source), string(AppendHTMLEscapedString(nil, input)), "HTML policy, case %d", i)
		// encoding/json (Go 1.22+) writes \b and \f as short escapes where release
		// writes \u0008 and \u000c; the release bytes above cover those inputs.
		if utf8.ValidString(input) && !strings.ContainsAny(input, "\b\f") {
			standard, err := std.Marshal(input)
			require.NoError(t, err)
			require.Equal(t, string(standard), string(AppendHTMLEscapedString(nil, input)), "HTML policy matches encoding/json, case %d", i)
		}
	}
}

// TestStringPolicyASCIIDecisions checks every ASCII byte under every policy
// against the per-byte rule the writer applied before its policy table: a byte
// is written as itself unless it is a control byte, '"' or '\', or (HTML
// policy) '<', '>' or '&'.
func TestStringPolicyASCIIDecisions(t *testing.T) {
	for policy, write := range map[string]func([]byte, string) []byte{"source": AppendString, "html": AppendHTMLEscapedString, "log": AppendLogString} {
		for c := 0; c < utf8.RuneSelf; c++ {
			plain := c >= 0x20 && c != '"' && c != '\\' && (policy != "html" || c != '<' && c != '>' && c != '&')
			got := string(write(nil, string(rune(c))))
			if plain {
				require.Equal(t, `"`+string(rune(c))+`"`, got, "%s policy, byte %#x", policy, c)
			} else {
				require.NotEqual(t, `"`+string(rune(c))+`"`, got, "%s policy, byte %#x must be escaped", policy, c)
				require.True(t, std.Valid([]byte(got)), "%s policy, byte %#x", policy, c)
				var back string
				require.NoError(t, std.Unmarshal([]byte(got), &back))
				require.Equal(t, string(rune(c)), back, "%s policy, byte %#x round trip", policy, c)
			}
		}
	}
}
